import { resolve } from "node:path";
import { targetLabel } from "../channels/github/forward.js";
import { teamsCredentialEnv } from "../channels/teams/credentials.js";
import { TEAMS_CHANNEL_KIND } from "../channels/teams/teams-channel.js";
import { credentialEnvNameError } from "./credential-env-names.js";
import { CliError } from "./cli/errors.js";
import { CLI_COMMAND_NAME as CLI, PACKAGE_NAME } from "./distribution.js";
import { resolveAgentMounts } from "./discovery.js";
export { TEAMS_CHANNEL_KIND };
export function envKeyList(keys) {
    return [keys.appId, keys.appPassword, keys.tenantId];
}
export function teamsTarget(input) {
    const postRoute = input.routes.find((route) => route.method === "POST");
    if (postRoute === undefined) {
        const label = input.slug === "" ? input.channelId : `${input.slug}/${input.channelId}`;
        throw new CliError(`Teams channel ${label} has no POST route, so Teams has no messaging endpoint to call.`);
    }
    return { slug: input.slug, channelId: input.channelId, routePath: postRoute.path };
}
/** Why a CLI command cannot read the credentials of a channel that sets them in code. */
export function credentialsInCodeMessage(profile) {
    return `Teams channel ${targetLabel(profile)} sets its credentials in code, so the CLI cannot read them`;
}
export function teamsChannelProfiles(mounts) {
    return mounts.flatMap(({ slug, project }) => project.channels.flatMap((channel) => {
        const meta = channel.definition.meta;
        if (meta?.kind !== TEAMS_CHANNEL_KIND) {
            return [];
        }
        const target = teamsTarget({
            slug,
            channelId: channel.id,
            routes: channel.definition.routes ?? [],
        });
        return [
            {
                ...target,
                credentialEnv: credentialEnvOf(meta, channel.id),
                engagement: engagementOf(meta),
            },
        ];
    }));
}
export function selectTeamsChannelProfiles(profiles, input) {
    const matched = profiles.filter((profile) => (input.slug === undefined || profile.slug === input.slug) &&
        (input.channel === undefined || profile.channelId === input.channel));
    if (matched.length === 0) {
        throw new CliError(noneMatched(input.dir, profiles));
    }
    return matched;
}
export async function loadTeamsChannelProfile(input) {
    const profiles = teamsChannelProfiles(await resolveAgentMounts(resolve(input.dir)));
    const matched = selectTeamsChannelProfiles(profiles, input);
    if (matched.length !== 1) {
        throw new CliError(`more than one Teams channel matched. Pass --slug or --channel:\n${describeTargets(matched)}`);
    }
    return matched[0];
}
/** The SDK builds the Teams names from the stored prefix, so this rebuilds what the channel published. */
function credentialEnvOf(meta, channelId) {
    if (meta.credentialEnv === undefined) {
        return undefined;
    }
    const env = teamsCredentialEnv(meta.credentialEnv.envPrefix);
    const nameError = credentialEnvNameError(channelId, env);
    if (nameError !== undefined) {
        throw new CliError(nameError, { code: "invalid_argument" });
    }
    return env;
}
function engagementOf(meta) {
    const engagement = meta.teamsEngagement;
    if (engagement === undefined) {
        return undefined;
    }
    return {
        mentions: engagement.mentions,
        directMessages: engagement.directMessages,
        channelPosts: (engagement.channelPosts?.length ?? 0) > 0,
    };
}
function noneMatched(dir, profiles) {
    return profiles.length === 0
        ? `no Teams channel found. Run \`${CLI} channels teams init --dir ${dir}\` (the channel needs ${PACKAGE_NAME}/channels/teams).`
        : `no Teams channel matched --slug/--channel:\n${describeTargets(profiles)}`;
}
function describeTargets(targets) {
    return targets.map((target) => `  - ${targetLabel(target)}`).join("\n");
}
